public void export(ExportRequest req, OutputStream out) {
    int batchSize = 10_000;
    int offset = 0;
    boolean headerWritten = false;
    ExcelWriter writer = EasyExcel.write(out).build();
    try {
        while (true) {
            // 每批开始前检查一次取消标志，命中就正常收尾
            if (cancelFlag.get(req.getTaskId())) {
                markCancelled(req.getTaskId());
                break;
            }
            List<Map<String, Object>> rows = queryPage(req, offset, batchSize);
            if (rows.isEmpty()) {
                break;
            }
            WriteSheet sheet = headerWritten
                    ? EasyExcel.writerSheet(0).build()
                    : EasyExcel.writerSheet(0).head(buildHead(rows.get(0))).build();
            writer.write(rows, sheet);
            headerWritten = true;
            offset += batchSize;
            updateProgress(req.getTaskId(), offset);
        }
    } finally {
        writer.finish();          // 必须 finish，否则最后一批缓冲不会刷出去
    }
}

private void checkFullMode(ExportRequest req) {
    if (!MODE_FULL.equals(req.getMode())) {
        return;
    }
    long rows = countRows(req);
    if (rows > FULL_MODE_LIMIT_50K) {
        log.warn("full mode rejected, rows: {}, taskId: {}", rows, req.getTaskId());
        throw new BizException("数据量超过 5 万行，请使用流式导出");
    }
    log.info("full mode accepted, rows: {}, taskId: {}", rows, req.getTaskId());
}

// 分页与进度：offset 单调前进，进度按已导出行数估百分比
private List<Map<String, Object>> queryPage(ExportRequest req, int offset, int limit) {
    PagedSql paged = sqlPager.page(req.getTemplate(), req.getDataSource(), offset, limit);
    return sqlExecutor.query(paged.getSql(), paged.getParamMap());
}

private void updateProgress(Long taskId, int done) {
    Long total = totalRowsCache.get(taskId);
    if (total == null || total <= 0) {
        return;                       // 拿不到总数就不报进度，不猜百分比
    }
    int percent = (int) Math.min(99, done * 100L / total);
    progressDao.updateProgress(taskId, percent);
}

// 完全部置 100：循环里刻意封顶 99，避免「进度 100% 但文件还没落盘」
private void markFinished(Long taskId) {
    progressDao.updateProgress(taskId, 100);
    taskDao.updateStatus(taskId, STATUS_SUCCESS);
}
